SELECT CASE WHEN balance >= 65000 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_tier, account_type, ROUND(AVG(balance), 2) AS avg_balance, SORT_ARRAY(COLLECT_SET(account_type)) AS account_type_list, ROUND(AVG(balance), 2) AS avg_balance_2, COUNT(*) AS num_rows FROM accounts GROUP BY GROUPING SETS ((CASE WHEN balance >= 65000 THEN 'PREMIUM' ELSE 'STANDARD' END, account_type), (CASE WHEN balance >= 65000 THEN 'PREMIUM' ELSE 'STANDARD' END))
